import XCTest
final class NavigationTests:XCTestCase {
 func testNativeTabsAndControls(){let app=XCUIApplication();app.launch();XCTAssertTrue(app.tabBars.buttons["마켓"].waitForExistence(timeout:10));XCTAssertTrue(app.buttons["실시간 시세 연결"].exists);app.tabBars.buttons["관심"].tap();XCTAssertTrue(app.navigationBars["관심 종목"].exists);app.tabBars.buttons["연구실"].tap();XCTAssertTrue(app.buttons["CSV 백테스트 실행"].waitForExistence(timeout:5));app.tabBars.buttons["설정"].tap();XCTAssertTrue(app.navigationBars["설정"].exists);let shot=XCTAttachment(screenshot:app.screenshot());shot.name="native-settings";shot.lifetime = .keepAlways;add(shot)}
 func testSyntheticResearchReport(){let app=XCUIApplication();app.launch();app.tabBars.buttons["연구실"].tap();let demo=app.buttons["합성 테스트32봉 실행"];XCTAssertTrue(demo.waitForExistence(timeout:5));demo.tap();XCTAssertTrue(app.staticTexts["성과 리포트 · 모의 결과"].waitForExistence(timeout:5));app.swipeUp();let shot=XCTAttachment(screenshot:app.screenshot());shot.name="synthetic-research-report";shot.lifetime = .keepAlways;add(shot)}
 func testServerConfigurationScreen(){let app=XCUIApplication();app.launch();app.tabBars.buttons["연구실"].tap();let link=app.buttons["백그라운드 · Ubuntu 서버"];XCTAssertTrue(link.waitForExistence(timeout:5));link.tap();XCTAssertTrue(app.navigationBars["백그라운드 · 서버"].waitForExistence(timeout:5));XCTAssertTrue(app.secureTextFields["VIEW_TOKEN 또는 CONTROL_TOKEN"].exists);let shot=XCTAttachment(screenshot:app.screenshot());shot.name="ubuntu-server-config";shot.lifetime = .keepAlways;add(shot)}
}
